+import { expect } from 'chai';
+
+// Test the URL validation logic directly
+function isValidAuthTokenSyncURL(url: string): boolean {
+  try {
+    const parsed = new URL(url);
+    return parsed.protocol === 'https:' && 
+      /\.(google|googleapis|firebase|firebaseapp)\.com$/.test(parsed.hostname);
+  } catch {
+    return false;
+  }
+}
+
+describe('isValidAuthTokenSyncURL', () => {
+  it('should accept valid Google/Firebase URLs', () => {
+    expect(isValidAuthTokenSyncURL('https://accounts.google.com/token')).to.be.true;
+    expect(isValidAuthTokenSyncURL('https://securetoken.googleapis.com/v1/token')).to.be.true;
+    expect(isValidAuthTokenSyncURL('https://myapp.firebaseapp.com/__session')).to.be.true;
+    expect(isValidAuthTokenSyncURL('https://myapp.firebase.com/sync')).to.be.true;
+  });
+
+  it('should reject attacker-controlled URLs', () => {
+    expect(isValidAuthTokenSyncURL('https://evil.com/steal')).to.be.false;
+    expect(isValidAuthTokenSyncURL('https://google.com.evil.com/steal')).to.be.false;
+    expect(isValidAuthTokenSyncURL('http://accounts.google.com/token')).to.be.false; // not https
+    expect(isValidAuthTokenSyncURL('https://notgoogle.com')).to.be.false;
+    expect(isValidAuthTokenSyncURL('javascript:alert(1)')).to.be.false;
+    expect(isValidAuthTokenSyncURL('')).to.be.false;
+    expect(isValidAuthTokenSyncURL('not-a-url')).to.be.false;
+  });
+});

