+fn verify_qe_identity_signature(collateral: &Collateral) -> Result<(), Error> {
+    let qe_identity = collateral
+        .qe_identity
+        .as_ref()
+        .ok_or(Error::InvalidQeIdentity)?;
+
+    let qe_identity_signature = collateral
+        .qe_identity_signature
+        .as_ref()
+        .ok_or(Error::InvalidSignature)?;
+
+    let qe_identity_issuer_chain = collateral
+        .qe_identity_issuer_chain
+        .as_ref()
+        .ok_or(Error::InvalidCertChain)?;
+
+    // Parse the signing certificate (first cert in the chain)
+    let certs = parse_pem_cert_chain(qe_identity_issuer_chain)?;
+    if certs.is_empty() {
+        return Err(Error::InvalidCertChain);
+    }
+
+    let signing_cert = &certs[0];
+    let public_key = signing_cert
+        .tbs_certificate
+        .subject_pki
+        .subject_public_key
+        .data;
+
+    // Decode the signature from hex
+    let sig_bytes = hex::decode(qe_identity_signature).map_err(|_| Error::InvalidSignature)?;
+
+    // Convert raw r||s signature to DER-encoded ECDSA signature if needed
+    let der_sig = if sig_bytes.len() == 64 {
+        raw_ecdsa_to_der(&sig_bytes)?
+    } else {
+        sig_bytes
+    };
+
+    // Verify the signature over the QE Identity JSON body
+    let qe_identity_body = extract_json_body(qe_identity)?;
+
+    let peer_public_key =
+        signature::UnparsedPublicKey::new(&signature::ECDSA_P256_SHA256_ASN1, public_key);
+
+    peer_public_key
+        .verify(qe_identity_body.as_bytes(), &der_sig)
+        .map_err(|_| Error::InvalidSignature)?;
+
+    Ok(())
+}
