+    let qe_report = &quote.signed_data.qe_report;
+
+    // Verify MRSIGNER matches the expected QE MRSIGNER from Intel's QE Identity
+    if let Some(ref expected_mrsigner) = identity.mrsigner {
+        let expected_bytes = hex::decode(expected_mrsigner).map_err(|_| Error::InvalidQeIdentity)?;
+        if qe_report.mrsigner.as_ref() != expected_bytes.as_slice() {
+            return Err(Error::QeReportMrsignerMismatch);
