+                .map_err(|_| Error::InvalidQeIdentity)?;
+        let mask = u32::from_str_radix(miscselect_mask.trim_start_matches("0x"), 16)
+            .map_err(|_| Error::InvalidQeIdentity)?;
+        if (qe_report.miscselect & mask) != (expected & mask) {
+            return Err(Error::QeReportMiscselectMismatch);
