+pub fn verify_cert_signature(
+    cert: &X509Certificate,
+    issuer: &X509Certificate,
+) -> Result<(), Error> {
+    let issuer_public_key = issuer
+        .tbs_certificate
+        .subject_pki
+        .subject_public_key
+        .data;
+
+    let sig_alg = &cert.signature_algorithm;
+    let signature_value = cert.signature_value.data;
+    let tbs_der = cert.tbs_certificate.as_ref();
+
+    // Determine the verification algorithm based on the signature algorithm OID
+    let verify_result = if sig_alg.algorithm.to_string().contains("1.2.840.10045.4.3.2") {
+        // ECDSA with SHA-256
+        let peer_public_key = ring::signature::UnparsedPublicKey::new(
+            &ring::signature::ECDSA_P256_SHA256_ASN1,
+            issuer_public_key,
+        );
+        peer_public_key.verify(tbs_der, signature_value)
+    } else if sig_alg.algorithm.to_string().contains("1.2.840.10045.4.3.3") {
+        // ECDSA with SHA-384
+        let peer_public_key = ring::signature::UnparsedPublicKey::new(
+            &ring::signature::ECDSA_P384_SHA384_ASN1,
+            issuer_public_key,
+        );
+        peer_public_key.verify(tbs_der, signature_value)
+    } else {
+        return Err(Error::InvalidCertChain);
+    };
+
+    verify_result.map_err(|_| Error::InvalidCertChain)
+}
