+/// Convert a raw ECDSA signature (r || s, 64 bytes for P-256) to DER-encoded format
+pub fn raw_ecdsa_to_der(raw: &[u8]) -> Result<Vec<u8>, Error> {
+    if raw.len() != 64 {
+        return Err(Error::InvalidSignature);
+    }
+    let r = &raw[..32];
+    let s = &raw[32..];
+
+    fn encode_integer(val: &[u8]) -> Vec<u8> {
+        let mut v = val.to_vec();
+        // Remove leading zeros but keep at least one byte
+        while v.len() > 1 && v[0] == 0 {
+            v.remove(0);
+        }
+        // If high bit is set, prepend a zero byte
+        if v[0] & 0x80 != 0 {
+            v.insert(0, 0);
+        }
+        let mut result = vec![0x02, v.len() as u8];
+        result.extend_from_slice(&v);
+        result
+    }
+
+    let r_der = encode_integer(r);
+    let s_der = encode_integer(s);
+    let total_len = r_der.len() + s_der.len();
+    let mut der = vec![0x30, total_len as u8];
+    der.extend_from_slice(&r_der);
+    der.extend_from_slice(&s_der);
+    Ok(der)
+}
