+package org.apache.streampipes.rest.security;
+
+import java.net.InetAddress;
+import java.net.MalformedURLException;
+import java.net.URL;
+import java.net.UnknownHostException;
+import java.util.Set;
+
+public class EndpointUrlValidator {
+
+  private static final Set<String> ALLOWED_SCHEMES = Set.of("http", "https");
+
+  /**
+   * Validates that the given URL is safe to connect to, preventing SSRF attacks.
+   * Only allows HTTP/HTTPS schemes and rejects URLs pointing to internal/private networks.
+   *
+   * @param urlString the URL to validate
+   * @throws IllegalArgumentException if the URL is not safe
+   */
+  public static void validateEndpointUrl(String urlString) {
+    if (urlString == null || urlString.isBlank()) {
+      throw new IllegalArgumentException("Endpoint URL must not be empty");
+    }
+
+    URL url;
+    try {
+      url = new URL(urlString);
+    } catch (MalformedURLException e) {
+      throw new IllegalArgumentException("Invalid endpoint URL: " + e.getMessage());
+    }
+
+    // Validate scheme
+    String scheme = url.getProtocol().toLowerCase();
+    if (!ALLOWED_SCHEMES.contains(scheme)) {
+      throw new IllegalArgumentException("Only HTTP and HTTPS schemes are allowed for endpoint URLs");
+    }
+
+    // Validate host
+    String host = url.getHost();
+    if (host == null || host.isBlank()) {
+      throw new IllegalArgumentException("Endpoint URL must contain a valid host");
+    }
+
+    // Resolve the hostname and check for internal IPs
+    try {
+      InetAddress address = InetAddress.getByName(host);
+      if (isInternalAddress(address)) {
+        throw new IllegalArgumentException(
+            "Endpoint URL must not point to an internal/private network address");
+      }
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Cannot resolve endpoint host: " + host);
+    }
+  }
+
+  private static boolean isInternalAddress(InetAddress address) {
+    return address.isLoopbackAddress()
+        || address.isSiteLocalAddress()
+        || address.isLinkLocalAddress()
+        || address.isAnyLocalAddress()
+        || address.isMulticastAddress();
+  }
+}
