+/* @flow */
+
+import dns from 'dns';
+import net from 'net';
+
+/**
+ * Resolve a hostname and return the first IP address.
+ * This is used to pin DNS resolution and prevent TOCTOU race conditions
+ * via DNS rebinding attacks.
+ */
+export function resolveWithRecordType(hostname: string): Promise<?string> {
+  // If it's already an IP address, return it directly
+  if (net.isIP(hostname)) {
+    return Promise.resolve(hostname);
+  }
+
+  return new Promise((resolve, reject) => {
+    dns.lookup(hostname, {all: false}, (err, address) => {
+      if (err) {
+        reject(err);
+      } else {
+        resolve(address);
+      }
+    });
+  });
+}

