+ * Utility to detect potentially unsafe regular expressions that could cause
+ * catastrophic backtracking (ReDoS).
+ */
+
+// Detect patterns that are known to cause catastrophic backtracking:
+// - Nested quantifiers: (a+)+, (a*)*,  (a|a)*, etc.
+// - Overlapping alternations with quantifiers
+const UNSAFE_PATTERN = /([^\\]|^)\(([^)]*[+*]|[^)]*\|[^)]*)\)[+*{]/
+const STAR_HEIGHT_PATTERN = /([+*}])\s*[)]\s*[+*{]/
+
+/**
+ * Check if a regex pattern is potentially unsafe (could cause ReDoS).
+ * This is a heuristic check - it may have false positives but should
+ * catch the most common dangerous patterns.
+ */
+export function isSafePattern(pattern: string): boolean {
+  if (pattern.length > 1000) return false
+  try {
+    // Check for nested quantifiers which are the primary cause of catastrophic backtracking
+    // This detects patterns like (a+)+, (a*)+, (a|b)*, (a+|b+)+ etc.
+    if (hasNestedQuantifiers(pattern)) return false
+    return true
+  } catch {
+    return false
+  }
+}
+
+function hasNestedQuantifiers(pattern: string): boolean {
+  let depth = 0
+  let hasQuantifierInGroup = false
+  let i = 0
+  while (i < pattern.length) {
+    const ch = pattern[i]
+    if (ch === "\\" && i + 1 < pattern.length) {
+      i += 2
+      continue
+    }
+    if (ch === "[") {
+      // skip character class
+      i++
+      while (i < pattern.length && pattern[i] !== "]") {
+        if (pattern[i] === "\\") i++
+        i++
+      }
+      i++
+      continue
+    }
+    if (ch === "(") {
+      depth++
+      hasQuantifierInGroup = false
+    } else if (ch === ")") {
+      depth--
+      // Check if the next char is a quantifier and the group contained a quantifier or alternation
+      if (i + 1 < pattern.length && /[+*{]/.test(pattern[i + 1]) && hasQuantifierInGroup) {
+        return true
+      }
+    } else if (/[+*{]/.test(ch) && depth > 0) {
+      hasQuantifierInGroup = true
+    } else if (ch === "|" && depth > 0) {
+      hasQuantifierInGroup = true
+    }
+    i++
+  }
+  return false
+}
+
+export class SafeRegExp extends RegExp {
+  constructor(pattern: string, flags?: string) {
+    if (!isSafePattern(pattern)) {
+      throw new Error(`Potentially unsafe regular expression: ${pattern}`)
+    }
+    super(pattern, flags)
+  }
+}
