+/**
+ * Sanitizes a MIME type string to prevent code injection via Content-Type header.
+ * Only allows valid MIME type characters (alphanumeric, /, -, +, .) and
+ * rejects any Content-Type that contains potentially dangerous characters.
+ *
+ * @param mimeType - The raw MIME type string from the Content-Type header
+ * @returns The sanitized MIME type string
+ */
+export function sanitizeMimeType(mimeType: string): string {
+  if (!mimeType || typeof mimeType !== 'string') {
+    return '';
+  }
+
+  // Extract only the MIME type portion (before any parameters like charset)
+  const baseMimeType = mimeType.split(';')[0].trim();
+
+  // Validate against a strict allowlist of characters valid in MIME types
+  // Valid MIME types only contain: letters, digits, !, #, $, &, -, ^, _, ., +, /
+  // Reference: RFC 6838
+  const VALID_MIME_TYPE_REGEX = /^[a-zA-Z0-9][a-zA-Z0-9!#$&\-^_.+]*\/[a-zA-Z0-9][a-zA-Z0-9!#$&\-^_.+]*$/;
+
+  if (!VALID_MIME_TYPE_REGEX.test(baseMimeType)) {
+    return 'application/octet-stream';
+  }
+
+  return baseMimeType;
+}
